function validate([events]) {
  if (!Array.isArray(events) || events.length < 1 || events.length > 100000) return 'events needs 1 to 100000 entries.';
  for (const event of events) {
    if (!Array.isArray(event) || event.length !== 2 || !event.every(Number.isInteger)) return 'Each event is a pair [startDay, endDay] of integers.';
    if (event[0] < 1 || event[1] > 100000 || event[0] > event[1]) return 'Each event needs 1 <= startDay <= endDay <= 100000.';
  }
  return null;
}

