function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const spans = large ? [100000, 2500, 600] : [3, 6, 10];
  const lastDay = spans[Math.floor(rand() * spans.length)];
  const longest = large ? [1, 30, 5000][Math.floor(rand() * 3)] : 1 + Math.floor(rand() * 5);
  const events = [];
  for (let i = 0; i < n; i++) {
    const start = 1 + Math.floor(rand() * lastDay);
    const end = Math.min(lastDay, start + Math.floor(rand() * longest));
    events.push([start, end]);
  }
  return [events];
}
